<script setup lang="ts">
import {useHysRootAttrs} from '../../config'
const hysRootAttrs=useHysRootAttrs()
import {computed} from 'vue'
const props=withDefaults(defineProps<{value:number;showLabel?:boolean;color?:string;status?:'normal'|'success'|'warning'|'error';strokeWidth?:number;type?:'line'|'circle';width?:number;format?:(value:number)=>string;indeterminate?:boolean}>(),{showLabel:true,strokeWidth:7,type:'line',width:100,status:'normal'})
const value=computed(()=>Number.isFinite(props.value)?Math.max(0,Math.min(100,props.value)):0),fill=computed(()=>props.color||({normal:'',success:'#16a46e',warning:'#d9860c',error:'#ed4556'}[props.status]||'var(--hys-ui-primary,var(--hys-ui-theme-primary))'))
</script>
<template><div v-bind="hysRootAttrs" class="hys-ui-progress-line" :class="{'hys-ui-progress-circle':type==='circle'}" role="progressbar" :aria-valuenow="indeterminate?undefined:value" aria-valuemin="0" aria-valuemax="100" :style="type==='circle'?{width:width+'px',height:width+'px'}:undefined"><svg v-if="type==='circle'" viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="44" fill="none" :stroke-width="strokeWidth" stroke="var(--hys-ui-border,var(--hys-ui-theme-border))"/><circle cx="50" cy="50" r="44" fill="none" :stroke-width="strokeWidth" :stroke="fill" stroke-linecap="round" :stroke-dasharray="276.46" :stroke-dashoffset="276.46*(1-value/100)" transform="rotate(-90 50 50)"/></svg><div v-else class="hys-ui-progress-track" :style="{height:strokeWidth+'px'}"><div class="hys-ui-progress-fill hys-ui-motion-progress" :class="{'hys-ui-progress-indeterminate':indeterminate}" :style="{width:value+'%',height:'100%',background:fill}"/></div><span v-if="showLabel" class="hys-ui-progress-label"><slot :value="value">{{format?format(value):value+'%'}}</slot></span></div></template>
<style scoped>.hys-ui-progress-circle{position:relative;display:grid;place-items:center;flex:none}.hys-ui-progress-circle svg{width:100%;height:100%}.hys-ui-progress-circle .hys-ui-progress-label{position:absolute;font-size:16px}.hys-ui-progress-indeterminate{width:35%!important;animation:hys-ui-progress-slide 1.3s ease-in-out infinite}@keyframes hys-ui-progress-slide{0%{transform:translateX(-110%)}100%{transform:translateX(300%)}}</style>
